def route_by_risk(score):
    if type(score) is not int:
        return 'invalid'
    if score >= 8:
        return 'human_review'
    if score >= 4:
        return 'safe_diagnostics'
    return 'auto_answer'

def merge_state(state, update):
    result = dict(state)
    for key, value in update.items():
        if isinstance(result.get(key), list) and isinstance(value, list):
            result[key] = result[key] + value
        else:
            result[key] = value
    return result

def checkpoint_key(thread_id, step):
    if not isinstance(thread_id, str):
        return None
    tid = thread_id.strip()
    if not tid or not isinstance(step, int) or step < 0:
        return None
    return f'{tid}:{step}'

def validate_resume(command):
    if not isinstance(command, dict):
        return [False, 'invalid_command']

    action = command.get('action')
    if action not in {'approve', 'edit', 'reject'}:
        return [False, 'invalid_action']

    if action == 'edit':
        text = command.get('edited_text')
        if not isinstance(text, str) or not text.strip():
            return [False, 'missing_edit_text']

    return [True, 'ok']

