class StateGraph:
    def __init__(self):
        self._nodes = {}
        self._edges = {}
        self._state = None

    def add_node(self, name, handler):
        self._nodes[name] = handler
        return self

    def add_edge(self, from_node, to_node):
        self._edges.setdefault(from_node, []).append(to_node)
        return self

    def set_state(self, data):
        self._state = {'data': data, 'history': [], 'current': None}
        return self

    def step(self, node_name):
        if node_name not in self._nodes or self._state is None:
            return False
        self._state['history'].append(node_name)
        self._state['current'] = node_name
        return True

    def can_go_to(self, from_node, to_node):
        return to_node in self._edges.get(from_node, [])

    def history(self):
        return list(self._state['history']) if self._state else []

    def describe(self):
        return {'nodes': sorted(self._nodes.keys()), 'edges': dict(self._edges)}
